        Allure.label("feature", "Microservice Workflow");
        Allure.label("story", "test_negative_flow_S1020_v39_fault_Root1_SPECIAL_CHARACTERS");
        Allure.description("Microservice test scenario with " + totalSteps + " steps.");
        
